mapper.select:
SELECT t.template_id, t.approval_code, t.template_name, t.default_yn, t.active_yn,
       COALESCE((SELECT COUNT(*) FROM approval_line_template_step s WHERE s.template_id = t.template_id), 0)::int AS step_count,
       t.updated_at
  FROM approval_line_template t
 WHERE t.tenant_id = #{tenantId}
   AND t.owner_user_id = #{userId}

   AND t.approval_code = #{approvalCode}

   AND t.active_yn = TRUE
 ORDER BY t.default_yn DESC, t.updated_at DESC, t.template_id DESC

SELECT t.template_id, t.tenant_id, t.owner_user_id, t.approval_code,
       t.template_name, t.default_yn, t.active_yn
  FROM approval_line_template t
 WHERE t.template_id = #{templateId}
   AND t.tenant_id = #{tenantId}
   AND t.owner_user_id = #{userId}
 LIMIT 1

SELECT t.template_id, t.tenant_id, t.owner_user_id, t.approval_code,
       t.template_name, t.default_yn, t.active_yn
  FROM approval_line_template t
 WHERE t.tenant_id = #{tenantId}
   AND t.owner_user_id = #{userId}
   AND t.approval_code = #{approvalCode}
   AND t.default_yn = TRUE
   AND t.active_yn = TRUE
 LIMIT 1

mapper.insert:
INSERT INTO approval_line_template (
  tenant_id, approval_code, owner_user_id, template_name, default_yn
) VALUES (
  #{tenantId}, #{approvalCode}, #{userId}, #{templateName}, #{defaultYn}
)

mapper.update:
UPDATE approval_line_template
   SET template_name = #{templateName},
       default_yn = #{defaultYn},
       active_yn = #{activeYn},
       updated_at = NOW()
 WHERE template_id = #{templateId}
   AND tenant_id = #{tenantId}
   AND owner_user_id = #{userId}

mapper.delete:
DELETE FROM approval_line_template
 WHERE template_id = #{templateId}
   AND tenant_id = #{tenantId}
   AND owner_user_id = #{userId}

mapper.update:
UPDATE approval_line_template
   SET default_yn = FALSE
 WHERE tenant_id = #{tenantId}
   AND owner_user_id = #{userId}
   AND approval_code = #{approvalCode}
   AND default_yn = TRUE
